1:import type { ActionId, AgentReply, ReplyInteraction } from "./types.ts";
2:
3:function normalize(value: string): string {
4:  return value.normalize("NFD").replace(/\p{Diacritic}/gu, "").trim().toLowerCase();
5:}
6:
7:export function renderInteraction(interaction: ReplyInteraction | undefined): string {
8:  return interaction
9:    ? `\n\n${interaction.actions.map((action, index) => `${index + 1}. ${action.title}`).join("\n")}`
10:    : "";
11:}
12:
13:export function renderPlainText(reply: AgentReply): string {
14:  return `${reply.text}${renderInteraction(reply.interaction)}`;
15:}
16:
17:export function actionFromChoice(reply: AgentReply | null, value: string): ActionId | null {
18:  if (!reply?.interaction) {
19:    return null;
20:  }
21:  const choice = normalize(value);
22:  const index = Number(choice);
23:  if (Number.isInteger(index) && index >= 1 && index <= reply.interaction.actions.length) {
24:    return reply.interaction.actions[index - 1]?.id ?? null;
25:  }
26:  return reply.interaction.actions.find((action) => normalize(action.title) === choice)?.id ?? null;
27:}

