1:import { createServer } from "node:http";
2:import { AutoSeguroAgent } from "./agent.ts";
3:import { OpenAICompatibleLlm } from "./llm.ts";
4:import {
5:  createMetaHttpHandler,
6:  MetaGraphClient,
7:  MetaInbox,
8:  metaRuntimeConfig,
9:  MetaTransport,
10:} from "./meta.ts";
11:import { AuditLog, FileConversationStore } from "./persistence.ts";
12:import { QuoteClient } from "./quote-client.ts";
13:
14:function revision(): string {
15:  return process.env.REVISION ?? "unknown";
16:}
17:
18:function transportOptions(): { typingDelayMs: number; log: (event: Record<string, unknown>) => void } {
19:  return {
20:    typingDelayMs: Number(process.env.META_TYPING_DELAY_MS ?? "250"),
21:    log: (event) => console.log(JSON.stringify({
22:      service: "autoseguro-meta",
23:      revision: revision(),
24:      ...event,
25:    })),
26:  };
27:}
28:
29:async function main(): Promise<void> {
30:  const config = metaRuntimeConfig();
31:  const stateDirectory = process.env.STATE_DIR ?? ".runtime/conversations";
32:  const store = new FileConversationStore(stateDirectory);
33:  const agent = new AutoSeguroAgent(
34:    store,
35:    new AuditLog(process.env.AUDIT_LOG_PATH ?? ".runtime/audit.jsonl"),
36:    OpenAICompatibleLlm.fromEnv(),
37:    new QuoteClient({
38:      baseUrl: process.env.QUOTE_API_URL ?? "http://127.0.0.1:8000",
39:      timeoutMs: Number(process.env.QUOTE_TIMEOUT_MS ?? "3000"),
40:      maxAttempts: Number(process.env.QUOTE_MAX_ATTEMPTS ?? "3"),
41:    }),
42:  );
43:  const transport = new MetaTransport(
44:    agent,
45:    store,
46:    new MetaInbox(process.env.META_INTAKE_DIR ?? ".runtime/meta-intake", config.appSecret),
47:    new MetaGraphClient(config),
48:    config,
49:    transportOptions(),
50:  );
51:  const server = createServer(createMetaHttpHandler(config, transport, revision()));
52:  const port = Number(process.env.PORT ?? "3000");
53:  if (!Number.isInteger(port) || port < 1 || port > 65_535) {
54:    throw new Error("PORT inválida");
55:  }
56:  await new Promise<void>((resolve) => server.listen(port, "0.0.0.0", resolve));
57:  await transport.recover();
58:  console.log(JSON.stringify({
59:    service: "autoseguro-meta",
60:    revision: revision(),
61:    event: "server_started",
62:    port,
63:  }));
64:
65:  const shutdown = (): void => {
66:    transport.stop();
67:    server.close(() => process.exit(0));
68:  };
69:  process.on("SIGINT", shutdown);
70:  process.on("SIGTERM", shutdown);
71:}
72:
73:main().catch(() => {
74:  console.error("Falha ao iniciar o servidor AutoSeguro Meta");
75:  process.exitCode = 1;
76:});

