1:import { appendFile, mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
2:import { randomUUID } from "node:crypto";
3:import { dirname, join } from "node:path";
4:import { maskCep, redactSensitiveText } from "./privacy.ts";
5:import type {
6:  AuditEvent,
7:  CollectedFields,
8:  CollectedValue,
9:  ConversationState,
10:} from "./types.ts";
11:
12:const identifierPattern = /^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/u;
13:const stages = new Set(["collecting", "quoting", "resolved", "handoff", "closed"]);
14:
15:function statePath(directory: string, conversationId: string): string {
16:  if (!identifierPattern.test(conversationId)) {
17:    throw new Error("conversation_id inválido");
18:  }
19:  return join(directory, `${conversationId}.json`);
20:}
21:
22:function isRecord(value: unknown): value is Record<string, unknown> {
23:  return typeof value === "object" && value !== null && !Array.isArray(value);
24:}
25:
26:function isStateIdentity(value: unknown, conversationId: string): value is Record<string, unknown> {
27:  return isRecord(value)
28:    && (value.version === 2 || value.version === 3)
29:    && value.conversation_id === conversationId
30:    && typeof value.stage === "string"
31:    && stages.has(value.stage);
32:}
33:
34:function hasStateCollections(value: Record<string, unknown>): boolean {
35:  return isRecord(value.fields)
36:    && isRecord(value.processed_messages)
37:    && Array.isArray(value.quote_jobs)
38:    && Array.isArray(value.outbox)
39:    && typeof value.ambiguity_count === "number";
40:}
41:
42:function csatRating(value: unknown): "great" | "regular" | "bad" | null {
43:  return value === "great" || value === "regular" || value === "bad" ? value : null;
44:}
45:
46:function parseState(raw: string, conversationId: string): ConversationState {
47:  const value: unknown = JSON.parse(raw);
48:  if (!isStateIdentity(value, conversationId) || !hasStateCollections(value)) {
49:    throw new Error(`Estado inválido para ${conversationId}`);
50:  }
51:  return {
52:    ...value,
53:    version: 3,
54:    greeted: value.greeted === true,
55:    awaiting_csat: value.awaiting_csat === true,
56:    csat_rating: csatRating(value.csat_rating),
57:    csat_timestamp: typeof value.csat_timestamp === "string" ? value.csat_timestamp : null,
58:  } as ConversationState;
59:}
60:
61:function initialState(conversationId: string): ConversationState {
62:  return {
63:    version: 3,
64:    conversation_id: conversationId,
65:    stage: "collecting",
66:    fields: {},
67:    ambiguity_count: 0,
68:    processed_messages: {},
69:    active_quote_request_id: null,
70:    quote_jobs: [],
71:    outbox: [],
72:    quote: null,
73:    handoff_reason: null,
74:    greeted: false,
75:    awaiting_csat: false,
76:    csat_rating: null,
77:    csat_timestamp: null,
78:  };
79:}
80:
81:export class FileConversationStore {
82:  private readonly directory: string;
83:
84:  constructor(directory: string) {
85:    this.directory = directory;
86:  }
87:
88:  async load(conversationId: string): Promise<ConversationState> {
89:    const path = statePath(this.directory, conversationId);
90:    try {
91:      return parseState(await readFile(path, "utf8"), conversationId);
92:    } catch (error) {
93:      if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
94:        throw error;
95:      }
96:      return initialState(conversationId);
97:    }
98:  }
99:
100:  async save(state: ConversationState): Promise<void> {
101:    const path = statePath(this.directory, state.conversation_id);
102:    await mkdir(this.directory, { recursive: true });
103:    const temporaryPath = `${path}.${randomUUID()}.tmp`;
104:    await writeFile(temporaryPath, `${JSON.stringify(state, null, 2)}\n`, {
105:      encoding: "utf8",
106:      mode: 0o600,
107:    });
108:    await rename(temporaryPath, path);
109:  }
110:
111:  async reset(conversationId: string): Promise<void> {
112:    await rm(statePath(this.directory, conversationId), { force: true });
113:  }
114:}
115:
116:export function fieldsForAudit(
117:  fields: CollectedFields,
118:): Record<string, CollectedValue<unknown>> {
119:  return Object.fromEntries(
120:    Object.entries(fields).map(([name, collected]) => [
121:      name,
122:      name === "cep"
123:        ? { ...collected, value: maskCep(String(collected.value)) }
124:        : collected,
125:    ]),
126:  );
127:}
128:
129:export class AuditLog {
130:  private readonly path: string;
131:
132:  constructor(path: string) {
133:    this.path = path;
134:  }
135:
136:  async append(event: AuditEvent): Promise<void> {
137:    await mkdir(dirname(this.path), { recursive: true });
138:    const line = redactSensitiveText(JSON.stringify(event));
139:    await appendFile(this.path, `${line}\n`, { encoding: "utf8", mode: 0o600 });
140:  }
141:}

