1:import type {
2:  CandidateFields,
3:  CollectedFields,
4:  FieldOrigin,
5:  QuotePayload,
6:  RequiredFieldName,
7:} from "./types.ts";
8:import { requiredFieldNames } from "./types.ts";
9:
10:export interface ValidatedValues {
11:  plano?: string;
12:  idade?: number;
13:  veiculo_ano?: number;
14:  cep?: string;
15:  data_inicio?: string;
16:}
17:
18:export interface ValidationResult {
19:  values: ValidatedValues;
20:  errors: string[];
21:}
22:
23:function normalizePlan(value: unknown): string | null {
24:  if (typeof value !== "string") {
25:    return null;
26:  }
27:  const plan = value.normalize("NFD").replace(/\p{Diacritic}/gu, "").trim().toLowerCase();
28:  return ["essencial", "completo", "premium"].includes(plan) ? plan : null;
29:}
30:
31:function normalizeInteger(value: unknown, minimum: number, maximum: number): number | null {
32:  if (typeof value !== "number" && (typeof value !== "string" || !/^\d+$/u.test(value.trim()))) {
33:    return null;
34:  }
35:  const parsed = Number(value);
36:  return Number.isInteger(parsed) && parsed >= minimum && parsed <= maximum ? parsed : null;
37:}
38:
39:function normalizeCep(value: unknown): string | null {
40:  if (typeof value !== "string" && typeof value !== "number") {
41:    return null;
42:  }
43:  const digits = String(value).replace(/\D/gu, "");
44:  return digits.length === 8 ? `${digits.slice(0, 5)}-${digits.slice(5)}` : null;
45:}
46:
47:function normalizeDate(value: unknown, currentDate: string): string | null {
48:  if (typeof value !== "string") {
49:    return null;
50:  }
51:  const text = value.normalize("NFD").replace(/\p{Diacritic}/gu, "").trim().toLowerCase();
52:  const today = parseIsoDate(currentDate);
53:  if (!today) {
54:    return null;
55:  }
56:  if (text === "hoje" || text === "amanha") {
57:    const date = new Date(today);
58:    date.setUTCDate(date.getUTCDate() + (text === "amanha" ? 1 : 0));
59:    return date.toISOString().slice(0, 10);
60:  }
61:  const parts = /^([0-9]{2})\/([0-9]{2})\/([0-9]{4})$/u.exec(text);
62:  const iso = parts ? `${parts[3]}-${parts[2]}-${parts[1]}` : text;
63:  const date = parseIsoDate(iso);
64:  return date && date >= today ? iso : null;
65:}
66:
67:function parseIsoDate(value: string): Date | null {
68:  if (!/^\d{4}-\d{2}-\d{2}$/u.test(value)) {
69:    return null;
70:  }
71:  const [year, month, day] = value.split("-").map(Number);
72:  if (year === undefined || month === undefined || day === undefined) {
73:    return null;
74:  }
75:  const date = new Date(Date.UTC(year, month - 1, day));
76:  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day
77:    ? date
78:    : null;
79:}
80:
81:function assignIfPresent<T>(
82:  candidate: unknown,
83:  normalized: T | null,
84:  name: RequiredFieldName,
85:  label: string,
86:  values: ValidatedValues,
87:  errors: string[],
88:): void {
89:  if (candidate === undefined || candidate === null) {
90:    return;
91:  }
92:  if (normalized === null) {
93:    errors.push(`${label} inválido`);
94:    return;
95:  }
96:  Object.assign(values, { [name]: normalized });
97:}
98:
99:export function validateCandidates(
100:  candidates: CandidateFields,
101:  currentDate = new Date().toISOString().slice(0, 10),
102:): ValidationResult {
103:  const values: ValidatedValues = {};
104:  const errors: string[] = [];
105:  assignIfPresent(candidates.plano, normalizePlan(candidates.plano), "plano", "plano", values, errors);
106:  assignIfPresent(candidates.idade, normalizeInteger(candidates.idade, 0, 200), "idade", "idade", values, errors);
107:  assignIfPresent(
108:    candidates.veiculo_ano,
109:    normalizeInteger(candidates.veiculo_ano, 1950, 2100),
110:    "veiculo_ano",
111:    "ano do veículo",
112:    values,
113:    errors,
114:  );
115:  assignIfPresent(candidates.cep, normalizeCep(candidates.cep), "cep", "CEP", values, errors);
116:  assignIfPresent(
117:    candidates.data_inicio,
118:    normalizeDate(candidates.data_inicio, currentDate),
119:    "data_inicio",
120:    "data de início",
121:    values,
122:    errors,
123:  );
124:  return { values, errors };
125:}
126:
127:export function validateField(
128:  name: RequiredFieldName,
129:  value: unknown,
130:  currentDate: string,
131:): ValidationResult {
132:  return validateCandidates({ [name]: value }, currentDate);
133:}
134:
135:export function mergeFields(
136:  fields: CollectedFields,
137:  values: ValidatedValues,
138:  messageId: string,
139:  source: FieldOrigin["source"] = "llm",
140:): CollectedFields {
141:  const merged = { ...fields };
142:  for (const [name, value] of Object.entries(values)) {
143:    Object.assign(merged, {
144:      [name]: { value, origin: { message_id: messageId, source } },
145:    });
146:  }
147:  return merged;
148:}
149:
150:export function hasFieldChanges(fields: CollectedFields, values: ValidatedValues): boolean {
151:  return Object.entries(values).some(([name, value]) => {
152:    const current = fields[name as RequiredFieldName];
153:    return current === undefined || current.value !== value;
154:  });
155:}
156:
157:export function missingFields(fields: CollectedFields): RequiredFieldName[] {
158:  return requiredFieldNames.filter((name) => fields[name] === undefined);
159:}
160:
161:export function toQuotePayload(fields: CollectedFields): QuotePayload {
162:  if (!fields.plano || !fields.idade || !fields.veiculo_ano || !fields.cep || !fields.data_inicio) {
163:    throw new Error("Campos obrigatórios incompletos");
164:  }
165:  return {
166:    plano_id: fields.plano.value,
167:    idade: fields.idade.value,
168:    veiculo_ano: fields.veiculo_ano.value,
169:    cep: fields.cep.value,
170:    data_inicio: fields.data_inicio.value,
171:  };
172:}

