28:  if (record.sender_role !== undefined && record.sender_role !== "lead") {
29:    return null;
30:  }
31:  const conversationId = typeof record.conversation_id === "string"
32:    ? record.conversation_id
33:    : fallbackConversationId;
34:  const text = typeof record.text === "string" ? record.text : record.message_body;
35:  const rawType = typeof record.message_type === "string" ? record.message_type : "text";
36:  if (typeof text !== "string" || !messageTypes.has(rawType as MessageType)) {
37:    throw new Error(`Linha ${index + 1} do replay é inválida`);
38:  }
39:  const sourceIndex = typeof record.message_index === "number" ? record.message_index : index;
40:  const messageId = typeof record.message_id === "string"
41:    ? record.message_id
42:    : `${conversationId}-${sourceIndex}`;
43:  return {
44:    conversation_id: conversationId,
45:    message_id: messageId,
46:    message_type: rawType as MessageType,
47:    text,
48:  };
