85:async function replay(path: string, conversationId: string, agent: AutoSeguroAgent): Promise<void> {
86:  const lines = (await readFile(path, "utf8")).split(/\r?\n/u).filter((line) => line.trim() !== "");
87:  let previous: AgentReply | null = null;
88:  for (const [index, line] of lines.entries()) {
89:    const message = readReplayRecord(line, conversationId, index);
90:    if (!message) {
91:      continue;
92:    }
93:    console.log(`Lead: ${redactSensitiveText(message.text)}`);
94:    const action = actionFromChoice(previous, message.text);
95:    const reply = await agent.handle(action ? { ...message, action } : message);
96:    printReply("AutoSeguro: ", reply);
97:    previous = reply;
98:  }
99:  await emitReady(agent, conversationId, (reply) => { previous = reply; });
100:}
