870:  config: MetaRuntimeConfig,
871:  transport: MetaTransport,
872:  revision = "unknown",
873:): (request: HttpRequest, response: ServerResponse) => Promise<void> {
874:  return async (request, response) => {
875:    const url = new URL(request.url ?? "/", config.publicBaseUrl);
876:    if (request.method === "GET" && url.pathname === "/health") {
877:      sendJson(response, 200, { status: "ok", revision });
878:      return;
879:    }
880:    if (request.method === "GET" && url.pathname === "/webhook") {
881:      verifyWebhook(url, config, response);
882:      return;
883:    }
884:    if (request.method !== "POST" || url.pathname !== "/webhook") {
885:      sendJson(response, 404, { error: "not_found" });
886:      return;
887:    }
888:    try {
889:      const body = await readBody(request);
890:      await transport.intake(body, firstHeader(request.headers["x-hub-signature-256"]));
891:      response.writeHead(200, { "content-type": "text/plain; charset=utf-8" });
892:      response.end("EVENT_RECEIVED");
893:      transport.kick();
894:    } catch (error) {
895:      const failure = error instanceof MetaWebhookError
